import{_ as r}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as o,o as e,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const b=JSON.parse('{"title":"Google Flow","description":"","frontmatter":{},"headers":[],"relativePath":"zh/products/ai-coding/gemini/flow.md","filePath":"zh/products/ai-coding/gemini/flow.md","lastUpdated":1787042982000}'),l={name:"zh/products/ai-coding/gemini/flow.md"};function s(n,t,i,g,d,h){return e(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="google-flow" tabindex="-1">Google Flow <a class="header-anchor" href="#google-flow" aria-label="Permalink to &quot;Google Flow&quot;">​</a></h1><blockquote><p>Google 的 AI 创意工作室。前端工程师用它做<strong>落地页宣传片、产品演示视频、场景分镜</strong>，不是写代码。</p><p>入口：<a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">labs.google/fx/tools/flow</a>。帮助中心：<a href="https://support.google.com/flow" target="_blank" rel="noreferrer">support.google.com/flow</a>。</p></blockquote><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>官方把它叫 <strong>AI creative studio</strong>：用自然语言做计划、生成、精修，底层是 Google 的生成式模型。</p><p>落地页当前列出三套模型：</p><table tabindex="0"><thead><tr><th>模型</th><th>官方一句话</th></tr></thead><tbody><tr><td><strong>Gemini Omni</strong></td><td>从任意输入参考（真实或生成）创建并编辑视频；强调世界理解、多模态与对话式编辑</td></tr><tr><td><strong>Nano Banana</strong></td><td>图像生成与精细编辑；强调主体一致性、文字渲染、推理</td></tr><tr><td><strong>Veo 3.1</strong></td><td>视频生成；强调物理、真实感、提示词遵循，带原生音频与扩展控制</td></tr></tbody></table><p>它不在编码主线上。对位 Claude 家族里的 <a href="./../claude/claude-design.html">Claude Design</a>：Design 出可交接的界面原型，Flow 出可发布的影像。</p><p><strong>年龄与语言</strong>：须满 18 岁。当前只能用英文向 Flow 发提示，回复也是英文。<a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">官方说明</a>。</p><h2 id="何时用" tabindex="-1">何时用 <a class="header-anchor" href="#何时用" aria-label="Permalink to &quot;何时用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>我要…</th><th>用</th><th>不要用 Flow</th></tr></thead><tbody><tr><td>落地页 / 宣传片 / 产品演示 <strong>视频</strong></td><td><strong>Flow</strong></td><td>Canvas 出的是能点的页面，不是成片</td></tr><tr><td>半小时内给产品经理一个 <strong>能点的原型</strong></td><td><a href="./canvas.html">Canvas</a></td><td>Flow 不做 DOM / 交互</td></tr><tr><td>把选定方案写进仓库</td><td><a href="./antigravity.html">Antigravity</a></td><td>Flow 不改代码、不出 PR</td></tr><tr><td>歌曲 / MV / 生成式配乐</td><td><a href="https://www.flowmusic.app/" target="_blank" rel="noreferrer">Flow Music</a>（积分与 Flow <strong>分开</strong>）</td><td>不要把 Flow 视频积分当成音乐积分</td></tr></tbody></table><p>实用组合：Canvas 试三个交互方向 → 选定一个 → Antigravity 在工程里实现；需要对外讲这个功能时，再用 Flow 出 8–10 秒演示片。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to &quot;能做什么&quot;">​</a></h2><p>来自 <a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">产品落地页</a> 与 <a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Pro 权益说明</a> 列出的能力：</p><ul><li><strong>生成模式</strong>：Text to video、Frames to video、Ingredients to video、Text to image、Image to image</li><li><strong>精修</strong>：Video Extension、Video-to-video editing、Scenebuilder</li><li><strong>角色</strong>：Characters、Avatars</li><li><strong>Agent</strong>：官方描述为项目级创意搭档，帮你探索和迭代</li><li><strong>自定义 Tools</strong>：用自然语言做工具（字幕叠层、改比例、分镜、shader），可分享 / remix。免费档只能<strong>使用</strong>已有 Tools；Plus 起才能<strong>创建</strong></li></ul><p><a href="https://support.google.com/flow/answer/16353334" target="_blank" rel="noreferrer">创建视频</a> 与 <a href="https://support.google.com/flow/answer/16935718" target="_blank" rel="noreferrer">编辑 / 搭场景</a> 是操作手册，本页不重复步骤。</p><h2 id="额度" tabindex="-1">额度 <a class="header-anchor" href="#额度" aria-label="Permalink to &quot;额度&quot;">​</a></h2><p>数字来自 <a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">Manage your Google Flow credits</a> 与落地页，<strong>不是</strong>从第三方博客抄的。</p><table tabindex="0"><thead><tr><th>档位</th><th>Flow 积分</th></tr></thead><tbody><tr><td>无订阅</td><td><strong>每天 50</strong>（试用；当日未用完不结转）</td></tr><tr><td>AI Plus</td><td><strong>每月 200</strong></td></tr><tr><td>AI Pro</td><td><strong>每月 1,000</strong></td></tr><tr><td>AI Ultra $100（本站称 Ultra 5x）</td><td><strong>每月 10,000</strong></td></tr><tr><td>AI Ultra $200（本站称 Ultra 20x）</td><td><strong>每月 25,000</strong></td></tr></tbody></table><p>要点：</p><ul><li>付费档按<strong>计费周期</strong>刷新，未用完的月度积分<strong>不结转</strong>。</li><li>升到付费档后，剩余的免费日积分立刻作废，换成该档月额度。</li><li>免费日积分只能用于 <strong>Veo 3.1 Lite / Fast / Quality</strong>。</li><li>用尽后，Plus / Pro / Ultra 可另购 AI credits 续用（日本除外）。同一笔 AI credits 也可用于 <a href="./antigravity.html">Antigravity</a>。</li><li>单次生成消耗因模型而异（例如非 Ultra 的 Veo 3.1 Lite 为 10 分、Quality 为 100 分）。以额度页的表为准，本页不另抄一份。</li></ul><p>四档存储、模型倍率、Cloud 额度等<strong>整张订阅表只在</strong><a href="./gemini-cheatsheet.html#订阅层级">速查表</a>。</p><h2 id="flow-sessions" tabindex="-1">Flow Sessions <a class="header-anchor" href="#flow-sessions" aria-label="Permalink to &quot;Flow Sessions&quot;">​</a></h2><p><a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">落地页</a> 上的 <strong>Flow Sessions</strong> 是艺术家合作计划：邀请一小批创作者用 Flow 做激情项目、并与 Google 合作。<strong>不是日常产品</strong>，前端工程师不需要单独学，也不要把它写成教程。</p><h2 id="常见坑" tabindex="-1">常见坑 <a class="header-anchor" href="#常见坑" aria-label="Permalink to &quot;常见坑&quot;">​</a></h2><ul><li>部分旧版 Labs 帮助仍写「必须订 Pro / Ultra 才能用」。以落地页和 <a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">额度页</a> 为准：无订阅可拿每天 50 分试用。</li><li>VPN <strong>不能</strong>绕过地区限制。先查 <a href="https://support.google.com/flow/answer/16353544" target="_blank" rel="noreferrer">Where you can use Flow</a>。</li><li>失败的生成不扣分；只要返回了结果就会扣，即使没有音频或质量不理想。</li><li>所有 Veo / Imagen 产出带不可见 SynthID。</li></ul><h2 id="官方资源" tabindex="-1">官方资源 <a class="header-anchor" href="#官方资源" aria-label="Permalink to &quot;官方资源&quot;">​</a></h2><ul><li><a href="https://labs.google/fx/tools/flow" target="_blank" rel="noreferrer">产品入口</a></li><li><a href="https://support.google.com/flow" target="_blank" rel="noreferrer">Flow 帮助中心</a></li><li><a href="https://support.google.com/flow/answer/16526234" target="_blank" rel="noreferrer">额度与单次消耗</a></li><li><a href="https://support.google.com/flow/answer/16353334" target="_blank" rel="noreferrer">创建视频</a></li><li><a href="https://support.google.com/googleone/answer/14534406" target="_blank" rel="noreferrer">Google AI Pro 权益清单</a></li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./google-pro.html">订阅与额度</a> — Pro 里还有哪些编码相关权益</li><li><a href="./canvas.html">Canvas</a> — 能点的原型</li><li><a href="./gemini-cheatsheet.html#选哪个工具">速查表</a> — 按任务选工具</li></ul>',29)])])}const w=r(l,[["render",s]]);export{b as __pageData,w as default};
